const $=(s,r=document)=>r.querySelector(s);
const esc=s=>String(s??'').replace(/[&<>"']/g,c=>({'&':'&amp;','<':'&lt;','>':'&gt;','"':'&quot;',"'":'&#39;'}[c]));
const arrow='<span class="arrow" aria-hidden="true">↗</span>';
const brand='<a class="brand" href="/" aria-label="Stillwell home"><span class="brand-mark" aria-hidden="true">s</span>stillwell</a>';
const seedPosts=[
{id:'p1',slug:'making-room-for-a-slower-day',title:'Making room for a slower day',category:'Everyday wellbeing',image:'/assets/slow.jpg',excerpt:'A few small ways to make a little more room in your everyday.',date:'2026-10-20',status:'published',body:'Some days arrive with a long list already attached. Before adding another thing, it can be useful to ask what could wait. A slower day does not need to be an empty one.\n\n## Start with a little space\nChoose one ordinary moment to leave unfilled. It could be your first cup of tea, a short walk without headphones, or a few minutes between meetings. Notice what you enjoy about that moment, without giving yourself another task to complete.\n\n## Make your own version\nThere is no single right pace. What feels spacious to one person might feel restless to another. Think about what you would like a little more of today: quiet, company, movement, or time to finish something.\n\n## Let enough be enough\nAt the end of the day, write down something you gave your attention to. It can be small. The purpose is simply to notice the life happening between the items on your list.'},
{id:'p2',slug:'you-dont-need-the-perfect-words',title:'You don’t need the perfect words',category:'Starting therapy',image:'/assets/talk.jpg',excerpt:'A thoughtful starting point for a first conversation.',date:'2026-10-17',status:'published',body:'Starting an unfamiliar conversation can feel awkward. You might have a lot to say, or not know where to begin. You do not need a polished explanation to ask questions about support.\n\n## Bring your questions\nBefore a first appointment, you can write down practical questions: how sessions work, what they cost, how privacy is handled, and what happens if you want to change providers.\n\n## Say what feels useful\nYou can start with what brought you there, what you hope to understand, or simply that you are unsure where to start. You can also ask about the provider’s approach and experience.\n\n## Take time to decide\nChoosing support is personal. Ask for the information you need and take time to consider whether the arrangement feels right for you.'},
{id:'p3',slug:'the-small-art-of-checking-in',title:'The small art of checking in',category:'Relationships',image:'/assets/walk.jpg',excerpt:'Making space for a more thoughtful everyday conversation.',date:'2026-10-14',status:'published',body:'A check-in can be as ordinary as asking someone how their afternoon went and making room for the answer. It does not have to become a big conversation.\n\n## Ask one open question\nTry a question that leaves room for a real answer: what stood out today, or what would you like to do this weekend? The details can matter more than finding the ideal question.\n\n## Leave room to listen\nLet the other person finish, and ask whether they want ideas or simply someone to listen. Sometimes spending time together is enough.\n\n## Find a moment that works\nA regular walk, shared meal, or short call can create a familiar place for conversation. Choose something that fits both of your lives.'},
{id:'p4',slug:'a-notebook-with-no-rules',title:'A notebook with no rules',category:'Everyday wellbeing',image:'/assets/journal.jpg',excerpt:'A blank page can be a place to begin, without a plan.',date:'2026-10-10',status:'published',body:'A notebook does not need to become a project. It can hold a shopping list, a sentence you liked, a question, or a few words about your day.\n\n## Begin anywhere\nWrite the date, something you noticed, or a thought you would like to return to. A single sentence counts as using the page.\n\n## Keep it yours\nThere is no need to make it beautiful or consistent. Pick a format you enjoy, whether that is pen and paper or a note on your phone.\n\n## Return when you want\nMissing a day does not undo anything. Your notebook is there when it is useful to you.'},
{id:'p5',slug:'finding-your-own-off-switch',title:'Finding your own off switch',category:'Everyday wellbeing',image:'/assets/slow.jpg',excerpt:'Creating a small separation between work and the rest of your day.',date:'2026-10-07',status:'published',body:'When work happens in the same place as everything else, the end of the day can feel less obvious. A small routine can help mark the transition.\n\n## Choose a closing moment\nWrite down where you will begin tomorrow, put your work things away, or close the door to your workspace. Pick something that suits your circumstances.\n\n## Make room for what comes next\nYou might change clothes, step outside, or make a meal. It does not need to be a productive routine. It only needs to feel like a different part of your day.'},
{id:'p6',slug:'questions-to-ask-before-you-begin',title:'Before your first session',category:'Starting therapy',image:'/assets/talk.jpg',excerpt:'Practical questions to bring to a potential care provider.',date:'2026-10-04',status:'draft',body:'Before choosing a provider, ask about qualifications, session format, fees, cancellations, and privacy.\n\n## Ask about the practical details\nFind out how appointments are arranged and what you can expect from the first meeting. Keep a note of anything you would like clarified.\n\n## Understand your choices\nAsk what options are available if you want to change the format or work with a different provider.'}
];
let storageFailed=false;
function readPosts(){try{const raw=localStorage.getItem('stillwell-posts');if(!raw)return structuredClone(seedPosts);const parsed=JSON.parse(raw);if(!Array.isArray(parsed)||parsed.some(p=>!p.id||!p.title||!p.slug||typeof p.body!=='string'))throw Error();return parsed;}catch{storageFailed=true;return structuredClone(seedPosts);}}
let posts=readPosts();let activeCare=0,blogCategory='All articles',blogSearch='',adminFilter='All posts',adminSearch='';let editorDirty=false;let theme;
try{theme=localStorage.getItem('stillwell-theme')}catch{}
document.documentElement.dataset.theme=theme||(matchMedia('(prefers-color-scheme: dark)').matches?'dark':'light');
function savePosts(next){try{localStorage.setItem('stillwell-posts',JSON.stringify(next));posts=next;return true;}catch{toast('Could not save. Browser storage may be full or unavailable.');return false;}}
const care=[
{name:'Individual therapy',heading:'A space that’s just yours.',text:'Explore what’s on your mind in a one-to-one conversation. Find room for the everyday, the unexpected, and everything in between.',image:'/assets/talk.jpg',alt:'A quiet, light-filled room with comfortable seating',details:['One-to-one support','At your own pace']},
{name:'Couples therapy',heading:'Make room for each other.',text:'A shared space to understand each other, explore the conversations that matter, and think about what comes next together.',image:'/assets/walk.jpg',alt:'A family spending time together outdoors',details:['Shared conversations','Thoughtful support']},
{name:'Young adult support',heading:'Find your own footing.',text:'Changing routines, new relationships, and big decisions. Explore support for the transitions that come with early adulthood.',image:'/assets/slow.jpg',alt:'A peaceful landscape in natural light',details:['For adults 18+','Life transitions']}
];
const faqs=[['How do I get started?','Explore the care options and choose what feels closest to your needs. In a live service, the next step would be a short introductory enquiry. This preview lets you explore that experience without booking an appointment.'],['Can I choose how we meet?','The proposed experience supports online and in-person preferences. Available formats, locations, and appointment times will be confirmed by the care team before launch.'],['What if I’m not sure what I need?','You can begin with a general enquiry. You do not need to choose a service or share personal details to ask how the process works.'],['How much does it cost?','Fees and any payment or insurance arrangements will be added once they are confirmed by the client. This preview does not take payments.'],['How is my information handled?','This design preview does not send enquiry form entries to a care team. Blog edits are saved only in this browser. Production privacy terms, secure accounts, and data handling must be configured before launch.']];
function nav(){const path=location.pathname;return `<header class="header"><div class="wrap nav">${brand}<nav class="nav-links" aria-label="Main navigation">${[['/services','Our care'],['/#how-it-works','How it works'],['/about','About us'],['/blog','The journal']].map(([href,label])=>`<a href="${href}" ${path===href?'aria-current="page"':''}>${label}</a>`).join('')}</nav><div class="nav-end"><a class="text-link" href="/contact">Get in touch</a><button class="btn" data-action="care">Find your care ${arrow}</button><button class="menu-toggle" data-action="menu" aria-label="Open navigation" aria-expanded="false">☰</button></div></div></header>`;}
function footer(){return `<footer class="wrap footer"><div class="footer-top"><div class="footer-brand">${brand}<p>A little space for your mind.<br>A little more room for you.</p></div><div class="footer-col"><strong>Explore care</strong><a href="/services?care=0">Individual therapy</a><a href="/services?care=1">Couples therapy</a><a href="/services?care=2">Young adult support</a></div><div class="footer-col"><strong>Get to know us</strong><a href="/about">Our approach</a><a href="/blog">The journal</a><a href="/contact">Contact us</a></div><div class="footer-col"><strong>The essentials</strong><a href="/privacy">Privacy & terms</a><a href="/admin">Blog management</a><button class="icon-button" data-action="theme" aria-label="Switch color theme">◐</button></div></div><div class="footer-bottom"><span>© ${new Date().getFullYear()} Stillwell. A website concept.</span><p>Illustrative care services and editorial content. This preview does not provide care or accept appointments.</p></div></footer>`;}
function layout(content){return `${nav()}<main id="main">${content}</main>${footer()}`;}
function carePanel(){const c=care[activeCare];return `<div class="care-copy reveal"><h3>${c.heading}</h3><p>${c.text}</p><ul class="care-list">${c.details.map(d=>`<li>${d}</li>`).join('')}</ul><button class="text-link" data-action="care" data-choice="${activeCare}">Explore ${c.name.toLowerCase()} ${arrow}</button></div><img src="${c.image}" alt="${c.alt}" loading="lazy" width="650" height="420">`;}
function careSection(){return `<section class="wrap section" id="care"><div class="section-head"><h2 class="intro-title">Care that meets you<br>where you are.</h2><p>There’s no one way to feel. There’s no one way to begin.</p></div><div class="care-tabs" role="tablist" aria-label="Care options">${care.map((c,i)=>`<button class="tab" role="tab" id="care-tab-${i}" aria-controls="care-panel" aria-selected="${activeCare===i}" tabindex="${activeCare===i?0:-1}" data-action="care-tab" data-index="${i}">${c.name}</button>`).join('')}</div><div class="care-panel" id="care-panel" role="tabpanel" aria-labelledby="care-tab-${activeCare}">${carePanel()}</div></section>`;}
function howSection(){return `<section class="wrap" id="how-it-works"><div class="how-section"><div class="how-intro"><div><h2>A first step.<br>At your pace.</h2><p>Starting something new can feel big. We make space for the small steps.</p></div><a href="/contact" class="text-link">Let’s talk about it ${arrow}</a></div><div class="how-steps">${[['↗','Tell us a little about you','Start with what you’re looking for. Share only what you’re comfortable sharing.'],['↔','Find a connection','Explore the kind of support and conversation that feels right for you.'],['✓','Make space for yourself','Choose a time and a format that work with your everyday life.']].map(([icon,title,text])=>`<div class="step"><span class="step-icon" aria-hidden="true">${icon}</span><div><h3>${title}</h3><p>${text}</p></div></div>`).join('')}</div></div></section>`;}
function safeImage(src){return typeof src==='string'&&(/^\/assets\/[a-zA-Z0-9._-]+$/.test(src)||/^data:image\/(jpeg|png|webp);base64,[A-Za-z0-9+/=]+$/.test(src))?src:'/assets/slow.jpg';}
function dateLabel(date){return new Date(date+'T12:00:00').toLocaleDateString('en-GB',{day:'numeric',month:'short',year:'numeric'});}
function articleCard(p){return `<article class="article-card"><a href="/blog/${esc(p.slug)}" tabindex="-1" aria-hidden="true"><img src="${safeImage(p.image)}" alt="${esc(p.imageAlt||p.title)}" loading="lazy" width="600" height="460"></a><div><div class="article-meta"><span>${esc(p.category)}</span><span>${Math.max(2,Math.ceil(p.body.split(/\s+/).length/180))} min read</span></div><h3><a href="/blog/${esc(p.slug)}">${esc(p.title)}</a></h3><a class="text-link" href="/blog/${esc(p.slug)}">Read the story ${arrow}</a></div></article>`;}
function journalSection(){return `<section class="wrap section"><div class="section-head journal-heading"><div><h2>A little perspective.</h2><p>Thoughtful reads for being a little more human.</p></div><a href="/blog" class="text-link">Explore the journal ${arrow}</a></div><div class="article-grid">${posts.filter(p=>p.status==='published').slice(0,3).map(articleCard).join('')}</div></section>`;}
function faqSection(){return `<section class="wrap section" style="padding-top:20px"><div class="faq-grid"><div><h2>A few things<br>you might wonder.</h2><p>It’s okay to have questions.<br>We’re here to make things clearer.</p><a href="/contact" class="text-link">Ask us something ${arrow}</a></div><div class="faq-list">${faqs.map(([q,a])=>`<details><summary>${q}</summary><p>${a}</p></details>`).join('')}</div></div></section>`;}
function cta(){return `<section class="wrap"><div class="cta"><div><h2>A little support.<br>A place to begin.</h2><p>Start wherever you are. We’ll meet you there.</p></div><button class="btn" data-action="care">Find your starting point ${arrow}</button></div></section>`;}
function home(){return layout(`<section class="wrap hero"><div class="hero-copy"><h1>A little space.<br>A lighter you.</h1><p>Thoughtful mental health support, built around you and the life you’re living.</p><div class="hero-actions"><button class="btn" data-action="care">Find your care ${arrow}</button><a href="#how-it-works" class="text-link">How it works <span class="arrow" aria-hidden="true">↓</span></a></div></div><img class="hero-image" src="/assets/hero.webp" alt="A woman enjoying a quiet moment in the afternoon sunlight" fetchpriority="high" width="800" height="850"></section><div class="wrap"><div class="benefits"><span><i aria-hidden="true">✓</i> Your space, without judgment</span><span><i aria-hidden="true">↔</i> Support that fits your life</span><span><i aria-hidden="true">♡</i> A more human kind of care</span></div></div>${careSection()}${howSection()}${journalSection()}${faqSection()}${cta()}`);}
function blog(){return layout(`<div class="wrap page-top"><a class="crumb" href="/">Home / The journal</a><h1>A little perspective.</h1><p>Stories, questions, and everyday moments. A space to pause and find something that speaks to you.</p></div><section class="wrap" style="padding-bottom:80px" aria-label="Journal articles"><div class="filter-bar"><div class="care-tabs">${['All articles','Everyday wellbeing','Starting therapy','Relationships'].map(c=>`<button class="tab ${blogCategory===c?'active':''}" aria-pressed="${blogCategory===c}" data-action="blog-filter" data-category="${c}">${c}</button>`).join('')}</div><input class="search" id="blog-search" type="search" value="${esc(blogSearch)}" placeholder="Search the journal" aria-label="Search articles"></div><div class="article-grid blog-grid" id="blog-results">${blogResults()}</div></section>${cta()}`);}
function blogResults(){const found=posts.filter(p=>p.status==='published'&&(blogCategory==='All articles'||p.category===blogCategory)&&(p.title+' '+p.excerpt+' '+p.body).toLowerCase().includes(blogSearch.toLowerCase()));return found.length?found.map(articleCard).join(''):'<div class="empty"><h3>No stories found.</h3><p>Try a different word or explore all articles.</p><button class="btn light" data-action="reset-blog">Show all articles</button></div>';}
function markdown(body){return body.split(/\n\s*\n/).map(t=>t.startsWith('## ')?`<h2>${esc(t.slice(3))}</h2>`:`<p>${esc(t).replace(/\*\*([^*]+)\*\*/g,'<strong>$1</strong>').replace(/\*([^*]+)\*/g,'<em>$1</em>').replace(/\n/g,'<br>')}</p>`).join('');}
function article(slug){const p=posts.find(p=>p.slug===slug&&p.status==='published');if(!p)return notFound();return layout(`<article class="wrap"><div class="article-hero"><a href="/blog" class="text-link">← Back to the journal</a><h1>${esc(p.title)}</h1><p>${esc(p.excerpt)}</p><div class="article-meta"><span>${esc(p.category)}</span><span>${dateLabel(p.date)}</span></div><img src="${safeImage(p.image)}" alt="${esc(p.imageAlt||p.title)}" width="900" height="500"></div><div class="article-body">${markdown(p.body)}<p class="note">From the Stillwell concept journal. Sample editorial content for this website preview, not personal clinical guidance.</p><a href="/blog" class="text-link">More from the journal ${arrow}</a></div></article><div style="height:70px"></div>${cta()}`);}
function about(){return layout(`<section class="wrap page-top"><a class="crumb" href="/">Home / About us</a><h1>More room to be human.</h1><p>Stillwell begins with a simple idea: support should make room for the whole person, not just the problem.</p></section><div class="wrap"><img class="about-image" src="/assets/hero.webp" alt="A quiet moment at home, surrounded by natural light" width="1300" height="600"></div><section class="wrap section"><h2>Care starts with listening.</h2><div class="values">${[['You set the pace','The first conversation is a starting point. You should have space to ask questions, think about your options, and decide what feels right.'],['A person, not a checklist','Your experiences, preferences, and everyday life belong in the conversation. There is no single story you need to fit.'],['Clarity from the beginning','Good information makes decisions easier. Our proposed care experience puts practical details and clear next steps where you can find them.'],['Room for everyday life','Support should fit into a real life. We are designing an experience that makes exploring options feel straightforward and human.']].map(([h,p])=>`<div><h3>${h}</h3><p>${p}</p></div>`).join('')}</div></section>${cta()}`);}
function contact(){return layout(`<div class="wrap page-top"><a class="crumb" href="/">Home / Get in touch</a><h1>Let’s talk.</h1><p>Have a question about care or how it works? You can start here.</p></div><section class="wrap contact-grid" style="padding-bottom:80px"><form class="form" id="contact-form"><div class="pair"><label>First name<input name="firstName" autocomplete="given-name" required maxlength="80"></label><label>Last name<input name="lastName" autocomplete="family-name" required maxlength="80"></label></div><label>Email address<input type="email" name="email" autocomplete="email" required maxlength="160"></label><label>What would you like to know?<select name="interest"><option>General enquiry</option>Individual therapy</option><option>Couples therapy</option><option>Young adult support</option></select></label><label>Your message<textarea name="message" maxlength="2000" required placeholder="Please keep your question general. No personal health details are needed."></textarea></label><label class="check-label"><input type="checkbox" required> I understand this is a website preview and my message will not be sent.</label><button class="btn" type="submit">Preview enquiry ${arrow}</button><p class="notice">Demo form. No email is sent and your enquiry is not stored.</p></form><aside class="contact-info"><h3>A little clarity first.</h3><p>You don’t need the perfect words. Ask about session formats, the process, or where to begin.</p><p>Service availability, fees, and contact details will be confirmed when the website launches.</p><p class="small">This preview is not a care service and cannot receive urgent requests.</p><a href="/#care" class="text-link">Explore the care options ${arrow}</a></aside></section>`);}
function privacy(){return layout(`<section class="wrap section legal"><h1>Privacy & preview terms</h1><h2>About this website</h2><p>Stillwell is an illustrative website concept. The brand, services, and articles are sample content. No appointments, payments, or clinical services are offered through this preview.</p><h2>What is stored</h2><p>The blog portal saves article changes and uploaded images in this browser’s local storage. Its demo session and theme preference also use browser storage. This is not a secure production account or a shared content system.</p><h2>Contact forms</h2><p>The enquiry form validates entries locally. It does not send an email or save submitted information. Please do not enter sensitive or personal health information.</p><h2>Before launch</h2><p>The client must supply final privacy terms, business details, approved service content, and editorial review. Secure authentication, shared content storage, and a contact delivery service must be configured before this becomes a live service.</p></section>`);}
function notFound(){return layout('<section class="wrap section"><h1>Let’s find your way back.</h1><p style="margin:25px 0">That page isn’t available. It may have moved or be unpublished.</p><a class="btn" href="/">Back to Stillwell</a></section>');}
function authenticated(){try{return sessionStorage.getItem('stillwell-demo')==='true'}catch{return false}}
function adminShell(content){return `<div class="admin-shell"><aside class="sidebar"><div>${brand}<p class="small">Publishing workspace</p></div><nav aria-label="Portal navigation"><a href="/admin" class="selected">All posts</a><a href="/admin/new">Create a post</a><a href="/blog">View journal ↗</a></nav><div class="bottom"><button class="text-link" style="border:0;background:none" data-action="logout">Exit workspace ↗</button></div></aside><main class="admin-main" id="main">${content}</main></div>`;}
function login(){return layout(`<div class="wrap"><section class="login"><p class="small">Stillwell publishing</p><h1>A home for your words.</h1><p>Create, edit, and preview stories for the journal.</p><div class="notice" style="background:var(--paper)">Demo workspace. Changes are saved in this browser only. Secure administrator sign-in is not connected.</div><button class="btn" style="width:100%;margin-top:25px" data-action="login">Open demo workspace ${arrow}</button><a class="text-link" href="/">← Back to the website</a></section></div>`);}
function admin(){return adminShell(`<div class="admin-header"><div><h1>Your journal</h1><p>A thoughtful space for every story.</p></div><a class="btn" href="/admin/new">+ Create a post</a></div><div class="notice">Demo workspace · Saved on this device. <a href="/privacy" style="text-decoration:underline">How this works</a>${storageFailed?'<p class="storage-error">Saved content could not be read. Sample articles are shown.</p>':''}</div><div class="stats"><div class="stat"><span>Total stories</span><strong>${posts.length}</strong></div><div class="stat"><span>Published</span><strong>${posts.filter(p=>p.status==='published').length}</strong></div><div class="stat"><span>Drafts</span><strong>${posts.filter(p=>p.status==='draft').length}</strong></div></div><div class="filter-bar"><div class="care-tabs">${['All posts','Published','Drafts'].map(f=>`<button class="tab ${adminFilter===f?'active':''}" aria-pressed="${adminFilter===f}" data-action="admin-filter" data-filter="${f}">${f}</button>`).join('')}</div><input class="search" id="admin-search" type="search" aria-label="Search posts" placeholder="Search posts" value="${esc(adminSearch)}"></div><div id="admin-results">${adminResults()}</div>`);}
function adminResults(){const found=posts.filter(p=>(adminFilter==='All posts'||p.status===(adminFilter==='Published'?'published':'draft'))&&p.title.toLowerCase().includes(adminSearch.toLowerCase()));return found.length?`<div class="table-wrap"><table class="post-table"><thead><tr><th>Story</th><th>Status</th><th>Date</th><th>Actions</th></tr></thead><tbody>${found.map(p=>`<tr><td><div class="post-cell"><img src="${safeImage(p.image)}" alt="" width="65" height="50"><div><strong><a href="/admin/edit/${esc(p.id)}">${esc(p.title)}</a></strong><small>${esc(p.category)}</small></div></div></td><td><span class="status ${p.status==='draft'?'draft':''}">${p.status==='published'?'Published':'Draft'}</span></td><td>${dateLabel(p.date)}</td><td><div class="row-actions"><a class="text-link" href="/admin/edit/${esc(p.id)}">Edit</a><button data-action="toggle-post" data-id="${esc(p.id)}">${p.status==='published'?'Unpublish':'Publish'}</button><button data-action="delete-post" data-id="${esc(p.id)}" aria-label="Delete ${esc(p.title)}">Delete</button></div></td></tr>`).join('')}</tbody></table></div>`:'<div class="empty"><h3>No posts here yet.</h3><p>Create a story or try another search.</p><a href="/admin/new" class="btn">Create a post</a></div>';}
function editor(id){const p=posts.find(p=>p.id===id)||{id:crypto.randomUUID(),slug:'',title:'',body:'',excerpt:'',image:'/assets/slow.jpg',imageAlt:'',category:'Everyday wellbeing',status:'draft',date:new Date().toISOString().slice(0,10)};return adminShell(`<div class="admin-header"><div><a class="text-link" href="/admin">← All posts</a><h1>${id?'Edit your story':'A new story starts here.'}</h1></div><button class="btn light" data-action="preview-post">Preview ${arrow}</button></div><form class="form" id="editor-form" data-id="${p.id}"><div class="editor-layout"><div class="editor-fields form"><label>Story title<input name="title" value="${esc(p.title)}" required maxlength="110" placeholder="Give your story a title"></label><label>Short introduction<textarea name="excerpt" style="min-height:85px" maxlength="260" placeholder="A sentence that invites the reader in">${esc(p.excerpt)}</textarea></label><div class="editor-toolbar" role="toolbar" aria-label="Text formatting"><button type="button" data-action="format" data-format="bold"><strong>B</strong></button><button type="button" data-action="format" data-format="italic"><em>I</em></button><button type="button" data-action="format" data-format="heading">Heading</button></div><label>Your story<textarea name="body" id="post-body" required placeholder="Start writing. Use the toolbar to add headings or emphasis.">${esc(p.body)}</textarea></label><p class="small">Use blank lines for paragraphs. Formatting is shown in Preview.</p></div><aside class="editor-settings form"><h3>Story details</h3><label>Featured image<img class="upload-preview" id="upload-preview" src="${safeImage(p.image)}" alt="Featured image preview"><input name="imageFile" type="file" accept="image/png,image/jpeg,image/webp"><input type="hidden" name="image" value="${safeImage(p.image)}"></label><p class="small">JPG, PNG, or WebP. Up to 2 MB.</p><label>Image description<input name="imageAlt" value="${esc(p.imageAlt||'')}" placeholder="Describe the image" maxlength="200"></label><label>Category<select name="category">${['Everyday wellbeing','Starting therapy','Relationships'].map(c=>`<option ${p.category===c?'selected':''}>${c}</option>`).join('')}</select></label><label>Article URL<input name="slug" value="${esc(p.slug)}" placeholder="your-story-title" pattern="[a-z0-9]+(?:-[a-z0-9]+)*" title="Use lowercase letters, numbers, and single hyphens"></label><label>Publication date<input type="date" name="date" value="${p.date}" required></label><label>Status<select name="status"><option value="draft" ${p.status==='draft'?'selected':''}>Draft</option><option value="published" ${p.status==='published'?'selected':''}>Published</option></select></label><button class="btn" type="submit">Save story ${arrow}</button><p class="small">Changes appear in this browser’s journal after saving as Published.</p><p class="small" id="editor-state" role="status">All changes saved</p></aside></div></form>`);}
function setMeta(title,description){document.title=title+' | Stillwell';$('meta[name=description]').content=description||'A thoughtful space for mental wellbeing, care, and everyday perspectives.';$('meta[property="og:title"]').content=document.title;$('meta[property="og:description"]').content=$('meta[name=description]').content;$('link[rel=canonical]').href='https://stillwell-care-tanuj.swoonywhale4.chatgpt.site'+location.pathname;}
function render(){const path=decodeURI(location.pathname).replace(/\/$/,'')||'/';let html,title;if(path.startsWith('/admin')){title='Publishing workspace';html=!authenticated()?login():path==='/admin/new'?editor():path.startsWith('/admin/edit/')?editor(path.split('/').pop()):admin();}else if(path==='/'){html=home();title='A little space for you';}else if(path==='/services'){const c=Number(new URLSearchParams(location.search).get('care'));activeCare=c>=0&&c<care.length?c:0;html=layout(`<div class="wrap page-top"><a class="crumb" href="/">Home / Our care</a><h1>Start where you are.</h1><p>Explore a kind of support that makes sense for you. You can take your time deciding.</p></div>${careSection()}${howSection()}<div style="height:75px"></div>${cta()}`);title='Our care';}else if(path==='/blog'){html=blog();title='The journal';}else if(path.startsWith('/blog/')){const p=posts.find(p=>p.slug===path.split('/').pop()&&p.status==='published');html=article(path.split('/').pop());title=p?.title||'Page not found';}else if(path==='/about'){html=about();title='Our approach';}else if(path==='/contact'){html=contact();title='Get in touch';}else if(path==='/privacy'){html=privacy();title='Privacy & preview terms';}else{html=notFound();title='Page not found';}$('#app').innerHTML=html;setMeta(title,posts.find(p=>'/blog/'+p.slug===path&&p.status==='published')?.excerpt);editorDirty=false;}
function navigate(url){if(editorDirty&&!confirm('Leave this story without saving your changes?'))return;history.pushState({},'',url);render();if(location.hash){requestAnimationFrame(()=>$(location.hash)?.scrollIntoView({behavior:'instant',block:'start'}))}else window.scrollTo(0,0);}
window.addEventListener('popstate',()=>{render();window.scrollTo(0,0)});
window.addEventListener('beforeunload',e=>{if(editorDirty){e.preventDefault();e.returnValue='';}});
let toastTimer;function toast(message){$('#toast').textContent=message;$('#toast').classList.add('show');clearTimeout(toastTimer);toastTimer=setTimeout(()=>$('#toast').classList.remove('show'),4000);}
function showDialog(content){const d=$('#care-dialog');d.innerHTML=`<button class="icon-button dialog-close" data-action="close-dialog" aria-label="Close dialog">×</button>${content}`;if(!d.open)d.showModal();}
function careDialog(choice){if(choice!==undefined){const c=care[Number(choice)];showDialog(`<h2>${c.name}</h2><p>${c.text}</p><div class="notice">You’re exploring a website concept. No booking is made and no personal details are collected here.</div><a class="btn" href="/contact" style="margin-top:25px" data-close-dialog>Explore an enquiry ${arrow}</a><button class="text-link" style="border:0;background:none;margin-left:18px" data-action="care">Back to options</button>`);return;}showDialog(`<h2>Where would you like to start?</h2><p>Choose what feels closest to you. It’s okay to explore.</p>${care.map((c,i)=>`<button class="choice" data-action="care" data-choice="${i}"><span><strong>${c.name}</strong><small>${c.details.join(' · ')}</small></span>${arrow}</button>`).join('')}<a href="/contact" class="text-link" data-close-dialog>I’m not sure yet ${arrow}</a>`);}
document.addEventListener('click',e=>{const a=e.target.closest('a[href]');if(a&&a.origin===location.origin&&!e.metaKey&&!e.ctrlKey&&!e.shiftKey&&e.button===0){e.preventDefault();if(a.hasAttribute('data-close-dialog'))$('#care-dialog').close();navigate(a.pathname+a.search+a.hash);return;}const b=e.target.closest('[data-action]');if(!b)return;const action=b.dataset.action;
if(action==='menu'){const open=$('.nav-links').classList.toggle('open');b.setAttribute('aria-expanded',open);b.setAttribute('aria-label',open?'Close navigation':'Open navigation');b.textContent=open?'×':'☰';}
if(action==='care')careDialog(b.dataset.choice);
if(action==='close-dialog')$('#care-dialog').close();
if(action==='theme'){const next=document.documentElement.dataset.theme==='dark'?'light':'dark';document.documentElement.dataset.theme=next;try{localStorage.setItem('stillwell-theme',next)}catch{}}
if(action==='care-tab'){activeCare=Number(b.dataset.index);document.querySelectorAll('[data-action=care-tab]').forEach(t=>{t.setAttribute('aria-selected',t===b);t.tabIndex=t===b?0:-1;});$('#care-panel').innerHTML=carePanel();$('#care-panel').setAttribute('aria-labelledby',b.id);}
if(action==='blog-filter'){blogCategory=b.dataset.category;document.querySelectorAll('[data-action=blog-filter]').forEach(t=>{t.classList.toggle('active',t===b);t.setAttribute('aria-pressed',t===b)});$('#blog-results').innerHTML=blogResults();}
if(action==='reset-blog'){blogCategory='All articles';blogSearch='';render();}
if(action==='admin-filter'){adminFilter=b.dataset.filter;document.querySelectorAll('[data-action=admin-filter]').forEach(t=>{t.classList.toggle('active',t===b);t.setAttribute('aria-pressed',t===b)});$('#admin-results').innerHTML=adminResults();}
if(action==='login'){try{sessionStorage.setItem('stillwell-demo','true');render()}catch{toast('Browser storage is unavailable. Please enable it to open the demo.')}}
if(action==='logout'){if(editorDirty&&!confirm('Exit without saving your changes?'))return;sessionStorage.removeItem('stillwell-demo');editorDirty=false;navigate('/admin');}
if(action==='toggle-post'){const next=posts.map(p=>p.id===b.dataset.id?{...p,status:p.status==='published'?'draft':'published'}:p);if(savePosts(next)){render();toast('Story status updated.');}}
if(action==='delete-post'){const p=posts.find(p=>p.id===b.dataset.id);showDialog(`<h2>Delete this story?</h2><p>“${esc(p.title)}” will be removed from this browser. This cannot be undone.</p><button class="btn" data-action="confirm-delete" data-id="${esc(p.id)}">Delete story</button> <button class="btn light" data-action="close-dialog">Keep story</button>`);}
if(action==='confirm-delete'){if(savePosts(posts.filter(p=>p.id!==b.dataset.id))){$('#care-dialog').close();render();toast('Story deleted.');}}
if(action==='format'){const t=$('#post-body'),start=t.selectionStart,end=t.selectionEnd;const selected=t.value.slice(start,end)||'Your text';const wrap=b.dataset.format==='bold'?`**${selected}**`:b.dataset.format==='italic'?`*${selected}*`:`\n\n## ${selected}\n\n`;t.setRangeText(wrap,start,end,'select');t.focus();editorDirty=true;$('#editor-state').textContent='Unsaved changes';}
if(action==='preview-post'){const f=$('#editor-form'),data=new FormData(f);showDialog(`<div class="preview-content"><p class="small">Story preview</p><h2>${esc(data.get('title')||'Untitled story')}</h2><p style="margin:20px 0">${esc(data.get('excerpt'))}</p><img src="${safeImage(data.get('image'))}" alt="${esc(data.get('imageAlt'))}" style="border-radius:15px;margin:20px 0"><div class="article-body">${markdown(data.get('body'))}</div></div>`);}
});
document.addEventListener('keydown',e=>{const tab=e.target.closest('[role=tab]');if(tab&&['ArrowLeft','ArrowRight','Home','End'].includes(e.key)){e.preventDefault();const tabs=[...document.querySelectorAll('[role=tab]')],i=tabs.indexOf(tab);const next=e.key==='Home'?0:e.key==='End'?tabs.length-1:(i+(e.key==='ArrowRight'?1:-1)+tabs.length)%tabs.length;tabs[next].focus();tabs[next].click();}});
document.addEventListener('input',e=>{if(e.target.id==='blog-search'){blogSearch=e.target.value;$('#blog-results').innerHTML=blogResults();}if(e.target.id==='admin-search'){adminSearch=e.target.value;$('#admin-results').innerHTML=adminResults();}if(e.target.closest('#editor-form')){editorDirty=true;$('#editor-state').textContent='Unsaved changes';}});
document.addEventListener('change',async e=>{if(e.target.name==='imageFile'){const file=e.target.files[0];if(!file)return;if(!['image/png','image/jpeg','image/webp'].includes(file.type)||file.size>2*1024*1024){toast('Choose a JPG, PNG, or WebP image smaller than 2 MB.');e.target.value='';return;}try{const url=await new Promise((resolve,reject)=>{const r=new FileReader();r.onload=()=>resolve(r.result);r.onerror=reject;r.readAsDataURL(file)});const decoded=new Image();decoded.src=url;await decoded.decode();$('#upload-preview').src=url;$('[name=image]',$('#editor-form')).value=url;editorDirty=true;$('#editor-state').textContent='Unsaved changes';}catch{toast('This file could not be opened as an image.');}}});
document.addEventListener('submit',e=>{if(e.target.id==='contact-form'){e.preventDefault();showDialog('<h2>Your enquiry preview is ready.</h2><p>The form is complete. In the live website, this would be sent to the care team.</p><div class="notice">No message was sent or stored. Connect an email delivery service before launch.</div><button class="btn" style="margin-top:25px" data-action="close-dialog">Back to the website</button>');e.target.reset();}if(e.target.id==='editor-form'){e.preventDefault();const f=e.target,d=new FormData(f);const title=d.get('title').trim(),body=d.get('body').trim();if(!title||!body){toast('Add a title and story content before saving.');return;}const slug=d.get('slug').trim()||title.toLowerCase().normalize('NFKD').replace(/[\u0300-\u036f]/g,'').replace(/[^a-z0-9]+/g,'-').replace(/^-|-$/g,'');if(!slug){toast('Add a URL using lowercase letters or numbers.');return;}if(posts.some(p=>p.slug===slug&&p.id!==f.dataset.id)){toast('That article URL is already in use. Please choose another.');$('[name=slug]',f).focus();return;}const p={id:f.dataset.id,title,body,slug,excerpt:d.get('excerpt').trim(),image:d.get('image'),imageAlt:d.get('imageAlt').trim(),category:d.get('category'),date:d.get('date'),status:d.get('status')};const existing=posts.findIndex(x=>x.id===p.id);const next=[...posts];if(existing>=0)next[existing]=p;else next.unshift(p);if(savePosts(next)){editorDirty=false;navigate('/admin');toast(p.status==='published'?'Story published in this browser.':'Draft saved.');}}});
$('#care-dialog').addEventListener('click',e=>{if(e.target===$('#care-dialog')){const r=e.target.getBoundingClientRect();if(e.clientX<r.left||e.clientX>r.right||e.clientY<r.top||e.clientY>r.bottom)e.target.close();}});
render();
